#!/bin/sh
# Writes Shared/Secrets.swift (git-ignored) for one reader's build.
# The widget token comes from WIDGET_TOKEN, else ../.widget-token (the first account's).
set -e
cd "$(dirname "$0")"
: "${READING_SERVER:?set READING_SERVER to the server URL, e.g. https://read.example.com}"
token=${WIDGET_TOKEN:-$(cat ../.widget-token)}
cat > Shared/Secrets.swift <<SWIFT
// Generated by make-secrets.sh. Do not commit.
enum Secrets {
    static let serverURL = "$READING_SERVER"
    static let widgetToken = "$token"
}
SWIFT
